import Foundation
import ImageIO
import SpendozaKit
import SwiftUI
import Testing
import UIKit
@testable import Spendoza

/// The app icon (R41): a placeholder drawn from the Banknote theme, a note-green field with the engraved dial in
/// paper and card tones and no text. The owner can replace the PNG at any time.
///
/// The PNG in the asset catalog is generated by `theArtworkRendersOpaqueAt1024`: run the test with
/// `TEST_RUNNER_WRITE_APP_ICON=1` in xcodebuild's environment to (re)write it.
@MainActor
struct AppIconTests {
    private static let iconURL = URL(fileURLWithPath: #filePath)
        .deletingLastPathComponent().deletingLastPathComponent()
        .appendingPathComponent("Spendoza/Resources/Assets.xcassets/AppIcon.appiconset/AppIcon.png")

    @Test func theBuiltAppHasAPrimaryIcon() throws {
        let icons = try #require(Bundle.main.object(forInfoDictionaryKey: "CFBundleIcons") as? [String: Any])
        let primary = try #require(icons["CFBundlePrimaryIcon"] as? [String: Any])
        #expect(primary["CFBundleIconName"] as? String == "AppIcon")
    }

    @Test func theCatalogIconIs1024AndOpaque() throws {
        let data = try Data(contentsOf: Self.iconURL)
        let image = try #require(UIImage(data: data)?.cgImage)
        #expect(image.width == 1024 && image.height == 1024)
        #expect([.none, .noneSkipLast, .noneSkipFirst].contains(image.alphaInfo), "the App Store rejects alpha")
    }

    @Test func theArtworkRendersOpaqueAt1024() throws {
        let png = try #require(Self.renderPNG())
        let image = try #require(UIImage(data: png)?.cgImage)
        #expect(image.width == 1024 && image.height == 1024)
        #expect([.none, .noneSkipLast, .noneSkipFirst].contains(image.alphaInfo))
        if ProcessInfo.processInfo.environment["WRITE_APP_ICON"] == "1" {
            try png.write(to: Self.iconURL)
        }
    }

    /// Renders `AppIconArtwork` into an opaque 1024 x 1024 PNG (no alpha channel).
    static func renderPNG() -> Data? {
        let renderer = ImageRenderer(content: AppIconArtwork().frame(width: 1024, height: 1024))
        renderer.scale = 1
        guard let drawn = renderer.cgImage,
              let space = CGColorSpace(name: CGColorSpace.sRGB),
              let context = CGContext(data: nil, width: 1024, height: 1024, bitsPerComponent: 8, bytesPerRow: 0,
                                      space: space, bitmapInfo: CGImageAlphaInfo.noneSkipLast.rawValue)
        else { return nil }
        context.draw(drawn, in: CGRect(x: 0, y: 0, width: 1024, height: 1024))
        guard let opaque = context.makeImage() else { return nil }
        let data = NSMutableData()
        guard let destination = CGImageDestinationCreateWithData(data, "public.png" as CFString, 1, nil) else { return nil }
        CGImageDestinationAddImage(destination, opaque, nil)
        return CGImageDestinationFinalize(destination) ? data as Data : nil
    }
}

/// The icon's artwork: the Health dial at icon scale, without the score.
struct AppIconArtwork: View {
    private static func color(_ hex: UInt32, _ opacity: Double = 1) -> Color {
        let rgb = RGB(hex: hex)
        return Color(.sRGB, red: rgb.r, green: rgb.g, blue: rgb.b, opacity: opacity)
    }

    private static let note = color(0x1E4A3B)
    private static let paper = 0xE9EEE6 as UInt32
    private static let card = 0xF4F7F2 as UInt32

    private static func point(_ hub: CGPoint, _ degrees: Double, _ length: CGFloat) -> CGPoint {
        let radians = degrees * .pi / 180
        return CGPoint(x: hub.x + length * cos(radians), y: hub.y - length * sin(radians))
    }

    var body: some View {
        Canvas { ctx, size in
            ctx.fill(Path(CGRect(origin: .zero, size: size)), with: .color(Self.note))
            let hub = CGPoint(x: 512, y: 660)
            let radius: CGFloat = 360

            // Guilloché: twelve ellipses, 15 degrees apart, above the hub.
            var engraving = ctx
            engraving.clip(to: Path(CGRect(x: 0, y: 0, width: 1024, height: hub.y)))
            let ellipse = Path(ellipseIn: CGRect(x: -322, y: -142, width: 644, height: 284))
            var lines = Path()
            for step in 0..<12 {
                let transform = CGAffineTransform(translationX: hub.x, y: hub.y).rotated(by: Double(step) * 15 * .pi / 180)
                lines.addPath(ellipse, transform: transform)
            }
            engraving.stroke(lines, with: .color(Self.color(Self.card, 0.28)), lineWidth: 2.4)

            // The three bands, lighter as the score rises.
            let tones: [Double] = [0.45, 0.72, 1]
            for (index, stop) in DialGeometry.bandStops.enumerated() {
                let start = DialGeometry.angle(forScore: stop.1.lowerBound) - (index > 0 ? 1.2 : 0)
                let end = DialGeometry.angle(forScore: stop.1.upperBound + 1) + (index < 2 ? 1.2 : 0)
                var arc = Path()
                arc.addArc(center: hub, radius: radius, startAngle: .degrees(-start), endAngle: .degrees(-end),
                           clockwise: false)
                ctx.stroke(arc, with: .color(Self.color(Self.paper, tones[index])),
                           style: StrokeStyle(lineWidth: 34, lineCap: .butt))
            }

            // The needle in the Good band, and the hub.
            var needle = Path()
            needle.move(to: hub)
            needle.addLine(to: Self.point(hub, DialGeometry.angle(forScore: 78), 300))
            ctx.stroke(needle, with: .color(Self.color(Self.card)), style: StrokeStyle(lineWidth: 16, lineCap: .round))
            let hubRadius: CGFloat = 62
            ctx.fill(Path(ellipseIn: CGRect(x: hub.x - hubRadius, y: hub.y - hubRadius,
                                            width: hubRadius * 2, height: hubRadius * 2)),
                     with: .color(Self.color(Self.paper)))
            ctx.stroke(Path(ellipseIn: CGRect(x: hub.x - 30, y: hub.y - 30, width: 60, height: 60)),
                       with: .color(Self.note.opacity(0.55)), lineWidth: 3)
        }
        .frame(width: 1024, height: 1024)
    }
}
